66	func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc) error {
67		start, err := client.StartDeviceAuth(ctx)
68		if err != nil {
69			return fmt.Errorf("start login: %w", err)
70		}
71	
72		fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
73	
74		approvalURL := chooseApprovalURL(start)
75	
76		if interactive.CanPromptInteractively() {
77			// chooseApprovalURL prefers the code-embedded verification_uri_complete,
78			// so opening the URL is usually all the user needs to do. The device
79			// code is printed above regardless, so it's still available to confirm
80			// against the page (RFC 8628 §3.3.1) or to enter on the bare-URI fallback.
81			fmt.Fprintf(outW, "Login URL:   %s\n\n", approvalURL)
82			fmt.Fprintf(outW, "Press Enter to open in browser...")
83	
84			// Read from /dev/tty so we get a real keypress and don't consume piped stdin.
85			if err := waitForEnter(ctx); err != nil {
86				return fmt.Errorf("wait for input: %w", err)
87			}
88	
89			fmt.Fprintln(outW)
90			if err := openURL(ctx, approvalURL); err != nil {
91				fmt.Fprintf(errW, "Warning: failed to open browser: %v\n", err)
92				fmt.Fprintf(outW, "Open this URL in your browser to approve this login: %s\n", approvalURL)
93			}
94		} else {
95			fmt.Fprintf(outW, "Login URL:   %s\n\n", approvalURL)
96		}
97	
98		fmt.Fprint(outW, "Waiting for approval... ")
99	
100		token, refreshToken, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, time.Duration(start.Interval)*time.Second, defaultSlowDownBackoff)
101		if err != nil {
102			return fmt.Errorf("complete login: %w", err)
103		}
104	
105		if err := validateReceivedToken(token, client.BaseURL(), time.Now()); err != nil {
106			return fmt.Errorf("reject login token: %w", err)
107		}
108	
109		store := auth.NewStore()
110	
111		// Login deliberately uses the legacy SaveToken (string, string)
112		// surface — we only have an access-token string at this point;
113		// the deviceflow client doesn't return a TokenSet here.
114		if err := store.SaveToken(client.BaseURL(), token); err != nil {
115			return fmt.Errorf("save auth token: %w", err)
116		}
117	
118		// Dual-write the shared contexts.json credential model so the git
119		// remote helper (and entiredb's CLIs) can authenticate against any
120		// entitled cluster from this login. Best-effort: the legacy entry
121		// above remains the control-plane source of truth, so a failure here
122		// must not fail the login — warn and continue.
123		if _, err := auth.RecordLoginContext(token, refreshToken, true); err != nil {
124			fmt.Fprintf(errW, "Warning: logged in, but could not record a shareable context (clone via entire:// may need a re-login): %v\n", err)
125		}
126	
127		fmt.Fprintln(outW, "✓ Login complete.")
128		return nil
129	}
