131	// validateReceivedToken runs minimum-trust checks on the access token
132	// the AS handed us before we persist it. The server is the authority
133	// on signature/exp; this is defense in depth aimed at catching gross
134	// misbehaviour by a compromised or misconfigured AS (e.g. handing back
135	// a token from a different issuer than the one we asked, or one whose
136	// claims are already-expired).
137	//
138	// Opaque (non-JWT) tokens are permitted — the AS may not issue JWTs at
139	// all. Only when we can parse the token as a JWT do we cross-check the
140	// claims. Unsigned (alg:none) JWTs are always rejected via
141	// tokens.ErrUnsignedJWT; every other parse failure (3-segment-but-not-
142	// base64, payload-not-JSON, header-not-JSON, etc.) is treated as opaque
143	// and accepted, so a server issuing dot-bearing non-JWT bearer tokens
144	// can still log in.
145	func validateReceivedToken(rawToken, issuerURL string, now time.Time) error {
146		claims, err := tokens.ParseClaims(rawToken)
147		if errors.Is(err, tokens.ErrUnsignedJWT) {
148			return err //nolint:wrapcheck // sentinel surfaces verbatim for caller's errors.Is
149		}
150		if err != nil {
151			return nil //nolint:nilerr // any parse failure other than alg:none means the token isn't a JWT — opaque tokens are valid
152		}
153	
154		// iss check: the token must claim to come from the issuer we sent
155		// the device-code request to. A mismatch means either the AS is
156		// misconfigured or someone's playing games.
157		if issErr := issMatches(claims.Issuer, issuerURL); issErr != nil {
158			return issErr
159		}
160	
161		// exp sanity: a token that's already expired before we even store
162		// it is a smell. Don't reject if exp is unset (some servers omit).
163		if !claims.ExpiresAt.IsZero() && !now.Before(claims.ExpiresAt) {
164			return fmt.Errorf("token already expired (exp=%s, now=%s)",
165				claims.ExpiresAt.Format(time.RFC3339), now.Format(time.RFC3339))
166		}
167	
168		return nil
169	}
170	
171	// issMatches reports whether claimed equals expected after stripping path/
172	// query/fragment via api.OriginOnly, so "https://issuer/" and "https://issuer"
173	// match. Returns nil on match or when the iss claim is empty (some servers
174	// omit it — the server still does the real check on every request).
175	func issMatches(claimed, expected string) error {
176		if claimed == "" {
177			return nil
178		}
179		normClaimed := api.OriginOnly(claimed)
180		normExpected := api.OriginOnly(expected)
181		if normClaimed != normExpected {
182			return fmt.Errorf("iss mismatch: token claims %q, expected %q", normClaimed, normExpected)
183		}
184		return nil
185	}
