	t.Setenv("ENTIRE_AUTH_BASE_URL", "http://devbox.internal:8787")
	c := NewClient(nil, true)
	if !c.inner.AllowInsecureHTTP {
		t.Fatal("NewClient(nil, true) AllowInsecureHTTP = false, want true")
	}
}

