1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net/http"
9		"sort"
10		"strings"
11		"time"
12	
13		"charm.land/lipgloss/v2"
14		"github.com/entireio/cli/cmd/entire/cli/api"
15		"github.com/entireio/cli/cmd/entire/cli/auth"
16		"github.com/entireio/cli/internal/coreapi"
17		"github.com/entireio/cli/internal/entireclient/contexts"
18		"github.com/spf13/cobra"
19	)
20	
21	// coreAuthSessionsPath is entire-core's login-session endpoint family
22	// (list / revoke / current) on the auth host. Sessions are OAuth
23	// refresh-token families; the CLI authenticates against them with its core
24	// JWT. Session management must target the auth host (entire-core), never the
25	// data host.
26	const coreAuthSessionsPath = "/api/auth/tokens"
27	
28	// User-visible placeholder strings. lastUsedJustNow is consumed by
29	// formatRelativeDuration in status.go.
30	const (
31		placeholderDash = "-"
32		lastUsedNever   = "never"
33		lastUsedJustNow = "just now"
34	)
35	
36	// requireSecureBaseURL enforces TLS unless insecureHTTPAuth is set. Every
37	// command that sends a bearer token over the network (login, logout,
38	// auth status) must call this so credentials don't leak over plaintext HTTP
39	// without explicit opt-in.
40	//
41	// Both the auth and data API origins are checked: the bearer travels to the
42	// auth host for login + session management, and to the data host for
43	// search/activity/dispatch/etc. When both origins resolve to the same host
44	// (e.g. an explicitly collapsed single-host deployment) the redundant second
45	// parse is skipped.
46	//
47	// When the opt-in flag is set, the tokenmanager's matching HTTP guard is
48	// also relaxed via auth.EnableInsecureHTTP — otherwise an STS exchange
49	// against a private-network http:// auth host would fail at the
50	// tokenmanager layer even though the per-command TLS check was waived.
51	func requireSecureBaseURL(insecureHTTPAuth bool) error {
52		if insecureHTTPAuth {
53			auth.EnableInsecureHTTP()
54			return nil
55		}
56		dataURL, authURL := api.BaseURL(), api.AuthBaseURL()
57		if err := api.RequireSecureURL(dataURL); err != nil {
58			return fmt.Errorf("base URL check: %w", err)
59		}
60		if authURL == dataURL {
61			return nil
62		}
63		if err := api.RequireSecureURL(authURL); err != nil {
64			return fmt.Errorf("auth base URL check: %w", err)
65		}
66		return nil
67	}
68	
69	// newAuthSessionsClient builds an api.Client for entire-core's login-session
70	// endpoints (coreAuthSessionsPath) on coreURL, authenticated with the
71	// session-scoped login JWT. coreURL is the active context's CoreURL (or the
72	// configured auth host when no context is active) — session management always
73	// targets a login server, never the data host.
74	func newAuthSessionsClient(coreURL, token string) *api.Client {
75		return api.NewClientWithBaseURL(token, coreURL).WithAuthSessionsPath(coreAuthSessionsPath)
76	}
77	
78	// isKeychainTokenRejected reports whether err indicates the stored
79	// keyring token can't authenticate against entire-core. Failure modes that
80	// collapse into the single "the user must re-login" branch:
81	//
82	//   - core API returned 401 (surfaces as *coreapi.ErrorModelStatusCode),
83	//     or a data API 401 (api.HTTPError),
84	//   - tokenmanager's preflight rejected an expired core token JWT
85	//     (surfacing as auth.ErrNotLoggedIn even though the keyring entry
86	//     is still present),
87	//   - the STS endpoint rejected the core token during exchange in a
88	//     split-host setup. auth-go's sts package returns the response as
89	//     "token exchange: status 4xx: <code>[: <desc>]" with no typed
90	//     sentinel exposed, so detection has to be by prefix. The "status
91	//     4" anchor catches the entire 4xx range — every 4xx from STS is
92	//     a credential problem, none are retryable without user action.
93	//
94	// Other shapes (network errors, malformed STS response, manager
95	// construction failures) deliberately don't match — the user sees the
96	// real diagnostic instead of a misleading "re-login" hint.
97	func isKeychainTokenRejected(err error) bool {
98		if api.IsHTTPErrorStatus(err, http.StatusUnauthorized) {
99			return true
100		}
101		// The /me liveness probe goes through the core API client, whose 401
102		// surfaces as *coreapi.ErrorModelStatusCode rather than api.HTTPError.
103		var coreErr *coreapi.ErrorModelStatusCode
104		if errors.As(err, &coreErr) && coreErr.StatusCode == http.StatusUnauthorized {
105			return true
106		}
107		if errors.Is(err, auth.ErrNotLoggedIn) {
108			return true
109		}
110		// A 401 whose body isn't JSON (e.g. a gateway returning text/plain) fails
111		// the ogen typed decode, so it never becomes an ErrorModelStatusCode — it
112		// arrives as a decode error whose message carries "(code 401)". Match that
113		// so the user still gets the re-login hint, not a raw decode dump.
114		if strings.Contains(err.Error(), "code 401") {
115			return true
116		}
117		return strings.Contains(err.Error(), "token exchange: status 4")
118	}
119	
120	// addInsecureHTTPAuthFlag attaches the hidden --insecure-http-auth flag used
121	// by every authenticated command for local development.
122	func addInsecureHTTPAuthFlag(cmd *cobra.Command, target *bool) {
123		cmd.Flags().BoolVar(target, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
124		if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
125			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
126		}
127	}
128	
129	func newAuthCmd() *cobra.Command {
130		cmd := &cobra.Command{
131			Use:   "auth",
132			Short: "Manage authentication",
133			Long:  "Authentication subcommands. Includes login, logout, status, and login-context management (contexts, use).",
134			RunE: func(cmd *cobra.Command, _ []string) error {
135				return cmd.Help()
136			},
137		}
138	
139		cmd.AddCommand(newLoginCmd())
140		cmd.AddCommand(newLogoutCmd())
141		cmd.AddCommand(newAuthStatusCmd())
142		cmd.AddCommand(newAuthContextsCmd())
143		cmd.AddCommand(newAuthUseCmd())
144		return cmd
145	}
146	
147	// --- status -----------------------------------------------------------------
148	
149	func newAuthStatusCmd() *cobra.Command {
150		var insecureHTTPAuth bool
151		cmd := &cobra.Command{
152			Use:   "status",
153			Short: "Show authentication status",
154			RunE: func(cmd *cobra.Command, _ []string) error {
155				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
156					return err
157				}
158				target, err := resolveStatusTarget(cmd.Context(), auth.NewContextStore(), auth.Contexts, auth.RefreshedLoginToken, api.AuthBaseURL())
159				if err != nil {
160					return err
161				}
162				// We send the session token to target.coreURL; enforce TLS on it
163				// too (it may differ from AuthBaseURL when a context is active).
164				if !insecureHTTPAuth {
165					if err := api.RequireSecureURL(target.coreURL); err != nil {
166						return fmt.Errorf("context login server URL check: %w", err)
167					}
168				}
169				return runAuthStatus(cmd.Context(), cmd.OutOrStdout(), defaultFetchProfile, defaultListAuthSessions, target)
170			},
171		}
172		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
173		return cmd
174	}
175	
176	// authProfile is the subset of the core API's GET /me that `entire auth
177	// status` renders.
178	type authProfile struct {
179		Handle         string
180		DisplayName    string
181		Email          string
182		Provider       string
183		ProviderUserID string
184	}
185	
186	// profileFetcher fetches a user's profile via GET /me on coreURL, authenticated
187	// with token. Injected so status stays unit-testable without a live core.
188	type profileFetcher func(ctx context.Context, coreURL, token string) (*authProfile, error)
189	
190	// authSessionLister lists the active login sessions on coreURL (the user's
191	// refresh-token families). Injected for testability; production wires
192	// defaultListAuthSessions.
193	type authSessionLister func(ctx context.Context, coreURL, token string) ([]api.AuthSession, error)
194	
195	// contextsProvider returns the stored login contexts and the active context
196	// name. Injected for testability; production wires auth.Contexts.
197	type contextsProvider func() ([]*contexts.Context, string, error)
198	
199	// loginTokenResolver returns a usable login JWT for a context, transparently
200	// re-minting an expired one from the stored refresh token. Injected so status
201	// tests don't reach the network; production wires auth.RefreshedLoginToken.
202	type loginTokenResolver func(ctx context.Context, c *contexts.Context) (string, error)
203	
204	// statusTarget is the resolved core to act against: the active context's
205	// CoreURL + its session token, or (no active context) the configured
206	// AuthBaseURL + legacy keyring entry. Shared by `auth status` (profile +
207	// session list) and `logout` (revocation) so both hit the same login server.
208	type statusTarget struct {
209		coreURL       string
210		token         string
211		activeContext string // "" when falling back to the legacy entry
212		totalContexts int
213	}
214	
215	// resolveStatusTarget picks the core + token for `entire auth status` (and
216	// `logout`). The active contexts.json context wins (so `auth use` retargets
217	// status onto that login server); otherwise it falls back to the legacy keyring
218	// entry keyed by the configured auth host.
219	//
220	// For the active context the token is resolved through resolveLogin, which
221	// transparently re-mints an expired login JWT from the stored refresh token.
222	// This is the point of the refresh: an expired-but-refreshable session must
223	// report "logged in", not "re-login" — the same false negative
224	// auth.ResolveControlPlaneTarget already avoids for org/repo/project/grant.
225	// `logout` benefits too: the refreshed bearer can authenticate the revoke call
226	// instead of failing on an expired token. When refresh fails (revoked family,
227	// network, opaque token), we fall back to the stored token and let the /me
228	// liveness probe be the arbiter — preserving the accurate "no longer valid"
229	// outcome for a genuinely dead session (ErrReauthRequired → expired token →
230	// 401 → re-login).
231	//
232	// A genuine contexts.json read/parse error is surfaced, not swallowed — a
233	// missing file reads as "no contexts" (no error), so an error here means the
234	// file is corrupt or unreadable, which the user must see. This keeps status
235	// symmetric with the control-plane commands (auth.ResolveControlPlaneTarget),
236	// which fail the same way rather than silently degrading to a stale identity.
237	func resolveStatusTarget(ctx context.Context, store tokenStore, listContexts contextsProvider, resolveLogin loginTokenResolver, fallbackBaseURL string) (statusTarget, error) {
238		all, current, err := listContexts()
239		if err != nil {
240			return statusTarget{}, fmt.Errorf("load contexts: %w", err)
241		}
242		total := len(all)
243		for _, c := range all {
244			if c.Name != current || c.CoreURL == "" {
245				continue
246			}
247			// Prefer a refreshed token; fall back to the raw stored token so a
248			// refresh failure degrades to today's behaviour rather than dropping
249			// to the legacy entry.
250			if tok, terr := resolveLogin(ctx, c); terr == nil && tok != "" {
251				return statusTarget{coreURL: c.CoreURL, token: tok, activeContext: c.Name, totalContexts: total}, nil
252			}
253			if tok, terr := auth.LoginTokenForContext(c); terr == nil && tok != "" {
254				return statusTarget{coreURL: c.CoreURL, token: tok, activeContext: c.Name, totalContexts: total}, nil
255			}
256		}
257		tok, gerr := store.GetToken(fallbackBaseURL)
258		if gerr != nil {
259			tok = "" // best-effort: a keyring read failure just reads as "no token"
260		}
261		return statusTarget{coreURL: fallbackBaseURL, token: tok, totalContexts: total}, nil
262	}
263	
264	// defaultFetchProfile fetches a user's profile from coreURL's GET /me with the
265	// given bearer. It doubles as the liveness check for `entire auth status`: a
266	// 401 (or an expired login) means the token is no longer usable, which
267	// isKeychainTokenRejected maps to a re-login hint.
268	func defaultFetchProfile(ctx context.Context, coreURL, token string) (*authProfile, error) {
269		client, err := coreapi.NewWithBearer(coreURL, token)
270		if err != nil {
271			return nil, fmt.Errorf("connect to %s: %w", coreURL, err)
272		}
273		me, err := client.GetMe(ctx)
274		if err != nil {
275			return nil, fmt.Errorf("fetch profile: %w", err)
276		}
277		p := &authProfile{
278			Provider:       me.Auth.Provider,
279			ProviderUserID: me.Auth.ProviderUserId,
280		}
281		p.Handle, _ = me.Global.Handle.Get()
282		if reg, ok := me.Regional.Get(); ok {
283			p.DisplayName, _ = reg.DisplayName.Get()
284			p.Email, _ = reg.Email.Get()
285		}
286		return p, nil
287	}
288	
289	// defaultListAuthSessions lists the user's active login sessions on coreURL.
290	func defaultListAuthSessions(ctx context.Context, coreURL, token string) ([]api.AuthSession, error) {
291		return newAuthSessionsClient(coreURL, token).ListAuthSessions(ctx) //nolint:wrapcheck // ListAuthSessions already wraps with action context
292	}
293	
294	// runAuthStatus reports auth state against the target core: GET /me validates
295	// the token and supplies the profile header, the active login context is shown
296	// locally, and the active sessions (refresh-token families) on that core are
297	// listed so the effect of `logout` / `logout --everywhere` is visible.
298	func runAuthStatus(ctx context.Context, w io.Writer, fetchProfile profileFetcher, listSessions authSessionLister, t statusTarget) error {
299		if t.token == "" {
300			fmt.Fprintf(w, "Not logged in to %s\n", t.coreURL)
301			fmt.Fprintln(w, "Run 'entire login' to authenticate.")
302			return nil
303		}
304	
305		profile, err := fetchProfile(ctx, t.coreURL, t.token)
306		if err != nil {
307			if isKeychainTokenRejected(err) {
308				fmt.Fprintf(w, "Login for %s is no longer valid.\n", t.coreURL)
309				fmt.Fprintln(w, "Run 'entire login' to re-authenticate.")
310				return nil
311			}
312			return fmt.Errorf("validate token: %w", err)
313		}
314	
315		fmt.Fprintf(w, "Logged in to %s\n", t.coreURL)
316		writeProfileLines(w, profile)
317		if t.activeContext != "" {
318			fmt.Fprintf(w, "  %-9s %s\n", "Context:", t.activeContext)
319		}
320		fmt.Fprintf(w, "  %-9s %s\n", "Token:", "stored in OS keychain")
321	
322		// Active sessions on this core. The token is already known good, so a
323		// listing failure is non-fatal — note it and carry on.
324		sessions, serr := listSessions(ctx, t.coreURL, t.token)
325		switch {
326		case serr != nil:
327			fmt.Fprintf(w, "\n(could not list active sessions: %v)\n", serr)
328		case len(sessions) > 0:
329			sortAuthSessionsByRecency(sessions)
330			fmt.Fprintf(w, "\nActive sessions (%d):\n", len(sessions))
331			renderAuthSessionsTable(w, newAuthTableStyles(w), sessions)
332			fmt.Fprintln(w, "\nRun 'entire logout' to end this session, or 'entire logout --everywhere' to end all of them.")
333		}
334	
335		if t.totalContexts > 1 {
336			fmt.Fprintln(w)
337			fmt.Fprintf(w, "%d login contexts saved; run 'entire auth contexts' to list or 'entire auth use <name>' to switch.\n", t.totalContexts)
338		}
339		return nil
340	}
341	
342	// writeProfileLines renders the user identity from GET /me as aligned
343	// label/value lines, omitting any field the server didn't populate.
344	func writeProfileLines(w io.Writer, p *authProfile) {
345		var parts []string
346		if p.DisplayName != "" {
347			parts = append(parts, p.DisplayName)
348		}
349		if p.Handle != "" {
350			parts = append(parts, "@"+p.Handle)
351		}
352		if p.Email != "" {
353			parts = append(parts, "<"+p.Email+">")
354		}
355		if len(parts) > 0 {
356			fmt.Fprintf(w, "  %-9s %s\n", "User:", strings.Join(parts, " "))
357		}
358		if p.Provider != "" {
359			identity := p.Provider
360			if p.ProviderUserID != "" {
361				identity += "/" + p.ProviderUserID
362			}
363			fmt.Fprintf(w, "  %-9s %s\n", "Identity:", identity)
364		}
365	}
366	
367	// --- auth tables -------------------------------------------------------------
368	
369	// authTableStyles holds the lipgloss styles for the `entire auth contexts`
370	// table. Mirrors the approach in activity_render.go: keep style construction
371	// tied to color detection, and render plain text when color is disabled.
372	type authTableStyles struct {
373		colorEnabled bool
374	
375		header lipgloss.Style // bold + dim, used for column headers
376		id     lipgloss.Style // yellow accent (active-context marker)
377		name   lipgloss.Style // bold (active context name)
378		value  lipgloss.Style // default fg
379	}
380	
381	func newAuthTableStyles(w io.Writer) authTableStyles {
382		useColor := shouldUseColor(w)
383		s := authTableStyles{colorEnabled: useColor}
384		if !useColor {
385			return s
386		}
387		s.header = lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true)
388		s.id = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
389		s.name = lipgloss.NewStyle().Bold(true)
390		s.value = lipgloss.NewStyle() // default fg
391		return s
392	}
393	
394	func (s authTableStyles) render(style lipgloss.Style, text string) string {
395		if !s.colorEnabled {
396			return text
397		}
398		return style.Render(text)
399	}
400	
401	// renderAlignedTable writes header followed by rows in left-aligned columns,
402	// sizing each column to its widest (possibly pre-styled) cell. Column widths
403	// use lipgloss.Width so ANSI escapes don't inflate the padding.
404	func renderAlignedTable(w io.Writer, header []string, rows [][]string) {
405		widths := make([]int, len(header))
406		for i, h := range header {
407			widths[i] = lipgloss.Width(h)
408		}
409		for _, row := range rows {
410			for i, c := range row {
411				if cw := lipgloss.Width(c); cw > widths[i] {
412					widths[i] = cw
413				}
414			}
415		}
416	
417		writeRow(w, header, widths)
418		for _, row := range rows {
419			writeRow(w, row, widths)
420		}
421	}
422	
423	func writeRow(w io.Writer, cells []string, widths []int) {
424		for i, c := range cells {
425			fmt.Fprint(w, c)
426			if i < len(cells)-1 {
427				fmt.Fprint(w, strings.Repeat(" ", widths[i]-lipgloss.Width(c)+2))
428			}
429		}
430		fmt.Fprintln(w)
431	}
432	
433	func fallback(s, alt string) string {
434		if strings.TrimSpace(s) == "" {
435			return alt
436		}
437		return s
438	}
439	
440	// renderAuthSessionsTable prints the active login sessions as an aligned table.
441	// No id column: there's no per-session CLI action (revoke-by-id is gone), so
442	// NAME/CREATED/LAST USED/EXPIRES is what's useful.
443	func renderAuthSessionsTable(w io.Writer, sty authTableStyles, sessions []api.AuthSession) {
444		header := []string{
445			sty.render(sty.header, "NAME"),
446			sty.render(sty.header, "CREATED"),
447			sty.render(sty.header, "LAST USED"),
448			sty.render(sty.header, "EXPIRES"),
449		}
450		rows := make([][]string, 0, len(sessions))
451		for _, s := range sessions {
452			rows = append(rows, []string{
453				sty.render(sty.name, fallback(s.Name, placeholderDash)),
454				sty.render(sty.value, formatAuthDate(s.CreatedAt)),
455				sty.render(sty.value, formatLastUsed(s.LastUsedAt)),
456				sty.render(sty.value, formatAuthDate(s.ExpiresAt)),
457			})
458		}
459		renderAlignedTable(w, header, rows)
460	}
461	
462	// sortAuthSessionsByRecency orders sessions most-recently-used first, then most
463	// recently created, then by id — a fully specified order independent of the
464	// server's response ordering.
465	func sortAuthSessionsByRecency(sessions []api.AuthSession) {
466		sort.Slice(sessions, func(i, j int) bool {
467			li, lj := lastUsedSortKey(sessions[i]), lastUsedSortKey(sessions[j])
468			if li != lj {
469				return li > lj
470			}
471			if sessions[i].CreatedAt != sessions[j].CreatedAt {
472				return sessions[i].CreatedAt > sessions[j].CreatedAt
473			}
474			return sessions[i].ID < sessions[j].ID
475		})
476	}
477	
478	func lastUsedSortKey(s api.AuthSession) string {
479		if s.LastUsedAt == nil {
480			return ""
481		}
482		return *s.LastUsedAt
483	}
484	
485	// formatAuthDate renders an RFC3339 timestamp as YYYY-MM-DD in local time,
486	// falling back to a dash (empty) or the raw value (unparseable).
487	func formatAuthDate(s string) string {
488		if s == "" {
489			return placeholderDash
490		}
491		if ts, err := time.Parse(time.RFC3339, s); err == nil {
492			return ts.Local().Format("2006-01-02")
493		}
494		return s
495	}
496	
497	func formatLastUsed(s *string) string {
498		if s == nil || *s == "" {
499			return lastUsedNever
500		}
501		return formatAuthDate(*s)
502	}
503

